@ParametersAreNonnullByDefault
public class ApplyImprovementOutcome
implements CraftingEffectOutcome {
    Map<String, Integer> improvements;
    StackMode stacking = StackMode.max;

    @Override
    public boolean apply(ResourceLocation[] unlockedEffects, ItemStack upgradedStack, String slot, boolean isReplacing, Player player, ItemStack[] preMaterials, Map<ToolAction, Integer> tools, Level world, UpgradeSchematic schematic, BlockPos pos, BlockState blockState, boolean consumeResources, ItemStack[] postMaterials, float severity) {
        return CastOptional.cast((Object)upgradedStack.m_41720_(), IModularItem.class).map(item -> item.getModuleFromSlot(upgradedStack, slot)).flatMap(module -> CastOptional.cast((Object)module, ItemModuleMajor.class)).map(module -> {
            AtomicBoolean result = new AtomicBoolean(false);
            for (Map.Entry<String, Integer> improvement : this.improvements.entrySet()) {
                String key = improvement.getKey();
                if (key.startsWith("#")) {
                    ItemAspect aspect = ItemAspect.get(key.substring(1));
                    Arrays.stream(module.getAcceptedImprovements(aspect)).collect(StreamHelper.toShuffledList()).stream().map(k -> new ImprovementPair((String)k, this.stacking.evaluate(module.getImprovementLevel(upgradedStack, (String)k), (Integer)improvement.getValue()))).filter(pair -> module.acceptsImprovementLevel(pair.key, pair.level)).findFirst().ifPresent(pair -> {
                        module.addImprovement(upgradedStack, pair.key, pair.level);
                        result.set(true);
                    });
                    continue;
                }
                int level = this.stacking.evaluate(module.getImprovementLevel(upgradedStack, key), improvement.getValue());
